class Solution:
    def countEquallySpaced(self, nums: list[int]) -> int:
        # Count occurrences of each number and store indices
        indices = defaultdict(list)
        for i, num in enumerate(nums):
            indices[num].append(i)

        count = 0
        for num, idx_list in indices.items():
            # Must have exactly 3 occurrences
            if len(idx_list) != 3:
                continue

            # Check if indices are equally spaced
            i1, i2, i3 = idx_list
            if i2 - i1 == i3 - i2:
                count += 1

        return count

