class Solution:
    def kthDigit(self, k: int) -> int:
        if k <= 9:
            return k

        def cum(b):
            if b == 0:
                return 9
            b_str = str(b)
            D = len(b_str)
            S = 0
            for d in range(1, D):
                count_d = 9 * (10 ** (d - 1))
                S += d * count_d
            start_D = 10 ** (D - 1)
            count_D = b - start_D + 1
            S += D * count_D
            return 9 + 10 * (S + b)

        low, high = 0, k
        while low < high:
            mid = (low + high) // 2
            c = cum(mid)
            if c < k:
                low = mid + 1
            else:
                high = mid
        b = low

        if b == 0:
            cum_prev = 0
        else:
            cum_prev = cum(b - 1)

        offset = k - cum_prev

        if b == 0:
            return 1 + (offset - 1)

        base = 10 * b
        L = len(str(base))
        num_idx = (offset - 1) // L
        digit_in_num = (offset - 1) % L

        if b % 2 == 0:
            num = base + num_idx
        else:
            num = base + 9 - num_idx

        num_str = str(num)
        return int(num_str[digit_in_num])

class Solution:
    def lastVisitedCell(self, grid: list[list[str]]) -> list[int]:
        m = len(grid)
        n = len(grid[0])
        visited = [[False] * n for _ in range(m)]
        r, c = 0, 0
        visited[0][0] = True
        while True:
            ch = grid[r][c]
            nr, nc = r, c
            if ch == 'L':
                nc -= 1
            elif ch == 'R':
                nc += 1
            elif ch == 'U':
                nr -= 1
            elif ch == 'D':
                nr += 1
            if nr < 0 or nr >= m or nc < 0 or nc >= n:
                break
            if visited[nr][nc]:
                break
            r, c = nr, nc
            visited[r][c] = True
        return [r, c]

