class Solution:
    def lastVisitedCell(self, grid: list[list[str]]) -> list[int]:
        m, n = len(grid), len(grid[0])
        visited = set()
        r, c = 0, 0
        visited.add((r, c))

        # directions
        dr = {'L': 0, 'R': 0, 'U': -1, 'D': 1}
        dc = {'L': -1, 'R': 1, 'U': 0, 'D': 0}

        while True:
            cur = grid[r][c]
            nr, nc = r + dr[cur], c + dc[cur]

            # check if move would go out of bounds
            if not (0 <= nr < m and 0 <= nc < n):
                break

            # check if target cell already visited
            if (nr, nc) in visited:
                break

            # move to next cell
            r, c = nr, nc
            visited.add((r, c))

        return [r, c]

