from collections import defaultdict, Counter

class Solution:
    def maxEqualPairs(self, nums: list[int]) -> int:
        n = len(nums)
        base = 0
        for i in range(n - 1):
            if nums[i] == nums[i + 1]:
                base += 1

        adj = defaultdict(Counter)
        for i in range(n):
            x = nums[i]
            if i - 1 >= 0 and nums[i - 1] != x:
                adj[x][nums[i - 1]] += 1
            if i + 1 < n and nums[i + 1] != x:
                adj[x][nums[i + 1]] += 1

        max_gain = 0
        for cnt in adj.values():
            if cnt:
                max_gain = max(max_gain, max(cnt.values()))

        return base + max_gain

