class Solution:
    def maxProductPair(self, nums: List[int], target: int) -> List[int]:
        n = len(nums)
        best_i = -1
        best_j = -1
        best_prod = None

        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if nums[i] + nums[j] == target and nums[i] > nums[j]:
                    prod = nums[i] * nums[j]
                    if best_prod is None:
                        best_i, best_j, best_prod = i, j, prod
                    else:
                        if prod > best_prod:
                            best_i, best_j, best_prod = i, j, prod
                        elif prod == best_prod:
                            # tie: smallest i, then smallest j
                            if i < best_i or (i == best_i and j < best_j):
                                best_i, best_j, best_prod = i, j, prod

        if best_prod is None:
            return [-1, -1]
        else:
            return [best_i, best_j]

