class Solution:
    def minDeletions(self, nums: list[int]) -> int:
        if len(nums) <= 1:
            return 0

        # Build the longest valid subsequence greedily
        subseq = [nums[0]]

        for i in range(1, len(nums)):
            if nums[i] != subseq[-1]:
                subseq.append(nums[i])

        return len(nums) - len(subseq)

